#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget constructed" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
};

void process() {
    auto ptr = std::make_unique<Widget>(); // creates a unique_ptr managing Widget
    // use ptr as needed
    // no manual delete required
}

int main() {
    process(); // Widget is automatically destroyed when ptr goes out of scope
    return 0;
}
